// 高精度阶乘
big mul4(int x){ 
    big z;
    z.num[0]=1;
    z.size=1;
    for(int j=2;j<=x;j++){
        int temp=0;
        for(int i=0;i<z.size;i++){
            z.num[i]=j*z.num[i]+temp;
            temp=z.num[i]/10;
            z.num[i]%=10;
        }
        while(temp>0){
            z.num[z.size]=temp%10;
            temp/=10;
            z.size++;
        }
    }
    clean(z);
    return z;
}

