    clean(y);
    if(x.size!=y.size) return x.size>y.size;
    else{
        for(int i=x.size-1;i>=0;i--){
            if(x.num[i]!=y.num[i]){
                return x.num[i]>y.num[i];
            }
        }
    }
}

